    // ========================================================================
    // Mejiro McQueen [Frontline Elegance] — JP 2021-03-02 / Global 2025-06-26
    // Aptitudes: Turf=A Dirt=E | Sprint=G Mile=F Medium=A Long=A | Pace=A Front=B Late=D End=F
